/// The CPU features `vg_keccak_pad_sha3` requires (`Artifact.features`).
pub(crate) const VG_KECCAK_PAD_SHA3_FEATURES: &[&str] = &["sha3"];

/// Pads a SHA-3 or SHAKE message: if the state `*state` represents a message whose length is `pos` modulo `rate` (`VG.Spec.Sha3.Repr`), it becomes the state after absorbing that message with the domain-separation suffix (the low byte of `suffix`, with the first bit of the padding: `0x06` for SHA-3, `0x1f` for SHAKE) and `pad10*1`.
///
/// Contract: `VG.Spec.Sha3.padContract`. Constant time: only the pointers, `rate`, `pos` and `suffix` may affect timing, not the state.
///
/// # Safety
///
/// * `state` must be valid for reads and writes of 200 bytes.
/// * `scratch` must be valid for reads and writes of 640 bytes.
/// * `rate` must be 72, 104, 136, 144 or 168, and `pos` less than `rate`.
/// * The contents of `scratch` on return are unspecified.
/// * `state` and `scratch` must not overlap each other (distinct Rust objects never do).
/// * Neither `state` nor `scratch` may overlap the 16 bytes of stack below the stack pointer, or wrap around the end of the address space (no Rust object does).
/// * The CPU must support the `sha3` target feature.
#[unsafe(naked)]
pub(crate) unsafe extern "C" fn vg_keccak_pad_sha3(state: *mut [u64; 25], rate: usize, pos: usize, suffix: u32, scratch: *mut [u64; 80]) {
    core::arch::naked_asm!(
        ".arch_extension sha3",
        "str x30, [sp, #-16]!",
        "add x9, x0, x2",
        "ldrb w10, [x9, #0]",
        "eor x10, x10, x3",
        "strb w10, [x9, #0]",
        "add x9, x0, x1",
        "sub x9, x9, #1",
        "ldrb w10, [x9, #0]",
        "movz x11, #128, lsl #0",
        "eor x10, x10, x11",
        "strb w10, [x9, #0]",
        "add x1, x4, #0",
        "bl {vg_keccak_f1600_sha3}",
        "ldr x30, [sp], #16",
        "ret",
        ".arch_extension nosha3",
        vg_keccak_f1600_sha3 = sym super::sha3::vg_keccak_f1600_sha3,
    )
}

